<?php declare(strict_types=1);namespace App\Application\Supplier;use RuntimeException;final class VerifySupplierNcc{public function execute(string$ncc):array{$ncc=strtoupper(trim($ncc));if(!preg_match('/^[A-Z0-9]{5,20}$/',$ncc))throw new RuntimeException('Le format du NCC est invalide.');$url='https://www.services.fne.dgi.gouv.ci/ws/ncc-verification?ncc='.rawurlencode($ncc);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CONNECTTIMEOUT=>7,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_error($ch);curl_close($ch);if($body===false||$code!==200)throw new RuntimeException('Le service de vérification DGI est indisponible'.($error!==''?' : '.$error:'.'));$data=json_decode((string)$body,true);if(!is_array($data)||empty($data['status'])||strtoupper((string)($data['ncc']??''))!==$ncc)throw new RuntimeException('Ce NCC n’a pas été reconnu comme valide par la DGI.');if(strtolower((string)($data['statusActivity']??''))!=='active')throw new RuntimeException('Ce contribuable n’est pas déclaré actif.');return['ncc'=>$ncc,'name'=>trim((string)($data['name']??'')),'tax_regime'=>(string)($data['taxRegime']??''),'activity_status'=>(string)($data['statusActivityLabel']??$data['statusActivity']??''),'payload'=>$data];}}
